DECLARE r jsonb; eid bigint; before_row public.catalog_edition_metadata;
BEGIN
FOR r IN SELECT value FROM jsonb_array_elements($records$[{"id":18,"authorId":14,"author":"Isaac Asimov","ol":"OL46125W","title":"De Foundation","isbn":"9789022979365","publisher":"A.W. Bruna","format":"paperback","description":"Het Galactische Imperium lijkt onaantastbaar, maar Hari Seldon voorspelt dat het zal uiteenvallen. Met zijn psychohistorie probeert hij de lange periode van chaos die daarna dreigt te verkorten. De Foundation moet daarbij kennis bewaren en toekomstige crises doorstaan. Asimov vertelt over politieke en maatschappelijke veranderingen op een schaal die het leven van één hoofdpersoon overstijgt. Dit is het eerste verschenen boek van de Foundation-reeks.","sourceUrl":"https://openlibrary.org/books/OL62852637M","sourceType":"official_catalog","sourceName":"openlibrary.org","supportingUrl":"https://openlibrary.org/books/OL62852637M","cover":"https://static.boekenbalie.nl/media/69/de/e4/1626410657/boekenbalie_9789022979365_cover.jpg","coverSource":"https://boekenbalie.nl/de-foundation/9789022979365","coverSha256":"0f20bef5ddb4d27e7d93e52e3cb861ae4515afbf539755877d54d89f4260ad1d","existingEdition":null},{"id":21,"authorId":17,"author":"Ursula K. Le Guin","ol":"OL59800W","title":"Duisters linkerhand","isbn":"9789029002813","publisher":"Meulenhoff","format":"paperback","description":"Een gezant bezoekt de ijzige planeet Gethen om contact te leggen namens een verbond van werelden. De gebruiken van de bewoners en hun omgang met gender blijken moeilijk te begrijpen vanuit zijn eigen denkbeelden. Politieke tegenstellingen maken zijn opdracht nog ingewikkelder. Duisters linkerhand verbindt een reis door een onbekende samenleving met vragen over vertrouwen, identiteit en de grenzen van het eigen perspectief. De roman verscheen ook als De linkerhand van het duister.","sourceUrl":"https://openlibrary.org/works/OL59800W","sourceType":"official_catalog","sourceName":"openlibrary.org","supportingUrl":"https://www.deslegte.com/duisters-linkerhand-944400/","cover":"https://static.boekenbalie.nl/media/31/2e/d9/1691523174/boekenbalie_9789029002813_cover.jpg","coverSource":"https://boekenbalie.nl/duisters-linkerhand/9789029002813","coverSha256":"c8827d5c41759ba5c7613994d25f5ad609292a3c48b736306a3e1c5816605d1e","existingEdition":null},{"id":27,"authorId":22,"author":"Terry Pratchett","ol":"OL453936W","title":"Good Omens","isbn":"9789022586631","publisher":"Boekerij","format":"paperback","description":"Een engel en een demon hebben zich zo aan het aardse leven gehecht dat het einde van de wereld hun slecht uitkomt. Terwijl de apocalyps nadert, blijkt ook de voorbereiding rond de antichrist anders te zijn verlopen dan gepland. Good Omens is de gezamenlijke roman van Terry Pratchett en Neil Gaiman. Hun verhaal combineert bovennatuurlijke dreiging met satire en alledaagse menselijke eigenaardigheden. De Nederlandse vertaling verscheen eerder als Hoge omens.","sourceUrl":"https://www.lannoo.com/nl-nl/fantasy-sciencefiction/good-omens-9789022586631","sourceType":"official_publisher","sourceName":"lannoo.com","supportingUrl":"https://www.lannoo.com/nl-nl/fantasy-sciencefiction/good-omens-9789022586631","cover":"https://static.boekenbalie.nl/media/0d/02/19/1630884860/boekenbalie_9789022586631_cover.jpg","coverSource":"https://boekenbalie.nl/good-omens/9789022586631","coverSha256":"d5fc49aa91be93f0ba7538235b7741fd453d0571294745669e435905486b91e2","existingEdition":null},{"id":140,"authorId":17,"author":"Ursula K. Le Guin","ol":"OL59863W","title":"De ontheemde","isbn":"9789027416810","publisher":"Het Spectrum","format":"paperback","description":"De natuurkundige Shevek is opgegroeid op Anarres, waar een samenleving zonder het vertrouwde bezit en gezag van de buurwereld is ingericht. Zijn wetenschappelijke werk brengt hem naar Urras. Daar ontdekt hij andere mogelijkheden, maar ook nieuwe vormen van ongelijkheid en afhankelijkheid. De ontheemde onderzoekt beide werelden zonder een eenvoudig ideaalbeeld te geven. Wetenschap, persoonlijke vrijheid en de vraag hoe mensen hun samenleving organiseren lopen door elkaar heen.","sourceUrl":"https://www.bibliotheek.nl/catalogus/titel.851052452.html/de-ontheemde/","sourceType":"official_catalog","sourceName":"bibliotheek.nl","supportingUrl":"https://www.bibliotheek.nl/catalogus/titel.851052452.html/de-ontheemde/","cover":"https://static.boekenbalie.nl/media/ec/81/cf/1626508986/boekenbalie_9789027416810_cover.jpg","coverSource":"https://boekenbalie.nl/de-ontheemde/9789027416810","coverSha256":"a6ea26f221ca6218796bfcc2e351bd2ae7030479d04a801548cce6ee4bf851c6","existingEdition":null},{"id":146,"authorId":120,"author":"Philip Pullman","ol":"OL28988W","title":"Het gouden kompas","isbn":"9789044611120","publisher":"Prometheus","format":"paperback","description":"Lyra gaat op zoek naar haar verdwenen vriend Roger en belandt in het verre Noorden. Haar wereld lijkt in sommige opzichten op de onze, maar wordt bevolkt door wezens en krachten die andere regels volgen. Een geheimzinnig instrument speelt een belangrijke rol in haar zoektocht. Het gouden kompas is het eerste deel van Pullmans Noorderlicht-trilogie. Deze Nederlandse roman verscheen oorspronkelijk onder de titel Het noorderlicht.","sourceUrl":"https://www.bibliotheek.nl/catalogus/titel.304650919.html/het-gouden-kompas/","sourceType":"official_catalog","sourceName":"bibliotheek.nl","supportingUrl":"https://www.bibliotheek.nl/catalogus/titel.304650919.html/het-gouden-kompas/","cover":"https://static.boekenbalie.nl/media/ab/dd/c8/1620300667/boekenbalie_9789044611120_cover.jpg","coverSource":"https://boekenbalie.nl/het-gouden-kompas/9789044611120","coverSha256":"4a3533356888ee8c6d5a2d8e498e22c13275544f9847d1faadec2297acf28a4a","existingEdition":null},{"id":218,"authorId":22,"author":"Terry Pratchett","ol":"OL453735W","title":"Wacht! Wacht!","isbn":"9789027433374","publisher":"Het Spectrum","format":"paperback","description":"In Ankh-Meurbork raakt de weinig indrukwekkende stadswacht betrokken bij een dreiging die de stad boven het hoofd groeit. Een draak brengt niet alleen gevaar, maar legt ook bloot hoe gemakkelijk mensen zich laten verleiden door macht en heldenverhalen. Wacht! Wacht! combineert een onderzoek met de absurditeit van Pratchetts Schijfwereld. Het is een ingang tot de verhalen rond de stadswacht, binnen de grotere reeks die verschillende personages volgt.","sourceUrl":"https://colinsmythe.co.uk/terry-pratchett/discworld/discworld-novels/guards-guards/","sourceType":"official_publisher","sourceName":"colinsmythe.co.uk","supportingUrl":"https://openlibrary.org/books/OL32879516M","cover":"https://covers.openlibrary.org/b/id/11511232-L.jpg","coverSource":"https://openlibrary.org/books/OL32879516M","coverSha256":"01c43b687a7a68e49830d2202f147edc11224e75a6827d7142cc6c16b221f673","existingEdition":null},{"id":288,"authorId":185,"author":"Dan Simmons","ol":"OL1963268W","title":"Hyperion","isbn":"9789024565184","publisher":"Luitingh-Sijthoff","format":"paperback","description":"Zeven pelgrims reizen naar de Tijdtombes op de planeet Hyperion. Ieder heeft een eigen reden om antwoorden te zoeken bij het mysterieuze wezen dat de Shrike wordt genoemd. Tijdens de tocht komen hun levensverhalen samen tegen de achtergrond van een naderend conflict. Hyperion wisselt perspectieven en vertelvormen af en bouwt zo stap voor stap een grotere wereld op. Het verhaal wordt voortgezet in De val van Hyperion.","sourceUrl":"https://www.bibliotheek.nl/catalogus/titel.372469205.html/hyperion/","sourceType":"official_catalog","sourceName":"bibliotheek.nl","supportingUrl":"https://www.bibliotheek.nl/catalogus/titel.372469205.html/hyperion/","cover":"https://static.boekenbalie.nl/media/f4/88/ef/1642797551/boekenbalie_9789024565184_cover.jpg","coverSource":"https://boekenbalie.nl/hyperion/9789024565184","coverSha256":"cdb4e956be5172582555efd2358f354ec9d2413cd219e009d446af4d2f5e9542","existingEdition":null},{"id":304,"authorId":191,"author":"Robin Hobb","ol":"OL2707183W","title":"Leerling en meester","isbn":"9789024598427","publisher":"Luitingh-Sijthoff","format":"paperback","description":"Fitz groeit als buitenechtelijke koningszoon op aan een hof waar zijn afkomst hem tegelijk waardevol en kwetsbaar maakt. Hij leert omgaan met politieke belangen, geheime opdrachten en bijzondere vermogens. Vertrouwen is schaars, terwijl hij nog moet ontdekken wie hij wil zijn. Leerling en meester is het eerste deel van De boeken van de Zieners. De Nederlandse vertaling van Assassin's Apprentice verscheen eerder als Moordenaarsleerling.","sourceUrl":"https://www.lsuitgeverij.nl/boek/leerling-en-meester/","sourceType":"official_publisher","sourceName":"lsuitgeverij.nl","supportingUrl":"https://www.lsuitgeverij.nl/boek/leerling-en-meester/","cover":"https://www.lsuitgeverij.nl/wp-content/uploads/2025/02/9789024598427_frontcover.jpg","coverSource":"https://www.lsuitgeverij.nl/boek/leerling-en-meester/","coverSha256":"c01d004d4ea31b409440a710bbee0e4db44a6f850cde913fbbfd73f46f0b5b81","existingEdition":null},{"id":1422,"authorId":749,"author":"Daniel Keyes","ol":"OL515754W","title":"Bloemen voor Algernon","isbn":"9789493456242","publisher":"Weerwoord","format":"paperback","description":"Charlie Gordon wil graag beter kunnen leren en begrijpen. Hij neemt deel aan een experiment dat zijn intelligentie moet vergroten, nadat het eerder bij de muis Algernon is toegepast. Zijn eigen verslagen laten zien hoe niet alleen zijn kennis, maar ook zijn relaties en zelfbeeld veranderen. Bloemen voor Algernon onderzoekt de betekenis van waardigheid en verbondenheid. De roman uit 1966 werkt het eerdere korte verhaal verder uit.","sourceUrl":"https://uitgeverijweerwoord.be/bloemen-voor-algernon/","sourceType":"official_publisher","sourceName":"uitgeverijweerwoord.be","supportingUrl":"https://uitgeverijweerwoord.be/bloemen-voor-algernon/","cover":"https://uitgeverijweerwoord.be/wp-content/uploads/2026/09/coverbloemen.jpg","coverSource":"https://uitgeverijweerwoord.be/bloemen-voor-algernon/","coverSha256":"12cd775e0fa9358da536e276f7c4f3c5e9e0ef77ef78a662719ad59e06f684b4","existingEdition":null},{"id":2146,"authorId":1076,"author":"J. M. Barrie","ol":"OL462007W","title":"Peter Pan","isbn":"9789025776183","publisher":"Gottmer","format":"hardcover","description":"Peter Pan neemt Wendy en haar broertjes mee naar Nooitland, waar zij tussen piraten, elfjes en de verloren jongens terechtkomen. Daar ontmoeten ze kapitein Haak en beleven ze avonturen buiten de regels van hun gewone leven. Achter de speelsheid schuilen vragen over opgroeien, herinneringen en afscheid. Deze Nederlandse editie is vertaald en licht bewerkt door Esther Ottens, met illustraties van Floor Rieder.","sourceUrl":"https://metadata.isbn.nl/1183115/peter-pan.html","sourceType":"official_catalog","sourceName":"metadata.isbn.nl","supportingUrl":"https://www.bruna.nl/boeken/peter-pan-9789025776183","cover":"https://static.boekenbalie.nl/media/bb/7a/eb/1791411963/boekenbalie_9789025776183_cover.jpeg","coverSource":"https://boekenbalie.nl/peter-pan/9789025776183","coverSha256":"2a08168f022db1579e209574d69ab4c4ad78cbde37924921778cf74759b4b598","existingEdition":null},{"id":2389,"authorId":961,"author":"Shirley Jackson","ol":"OL3171087W","title":"We hebben altijd in het kasteel gewoond","isbn":"9789020415391","publisher":"L.J. Veen Klassiek","format":"paperback","description":"Merricat woont met haar zus Constance en oom Julian in het huis van de familie Blackwood. Sinds een dodelijke gebeurtenis leven zij teruggetrokken, maar de buitenwereld laat hen niet met rust. De komst van neef Charles verstoort hun broze evenwicht. We hebben altijd in het kasteel gewoond maakt onzekerheid en dreiging voelbaar vanuit Merricats bijzondere blik. De korte roman draait om familiebanden, afzondering en de bescherming van een eigen wereld.","sourceUrl":"https://www.atlascontact.nl/boek/we-hebben-altijd-in-het-kasteel-gewoond/","sourceType":"official_publisher","sourceName":"atlascontact.nl","supportingUrl":"https://www.atlascontact.nl/boek/we-hebben-altijd-in-het-kasteel-gewoond/","cover":"https://www.atlascontact.nl/wp-content/uploads/2026/10/9789020415391_frontcover.jpg","coverSource":"https://www.atlascontact.nl/boek/we-hebben-altijd-in-het-kasteel-gewoond/","coverSha256":"f6de1b168aa9d972ebdb44c8d52fdf3af06886ccfb3cf26177b50e91fc99e5d3","existingEdition":null},{"id":2403,"authorId":1177,"author":"Colson Whitehead","ol":"OL17619932W","title":"De ondergrondse spoorweg","isbn":"9789025452391","publisher":"Atlas Contact","format":"paperback","description":"Cora leeft als tot slaaf gemaakte vrouw op een katoenplantage in Georgia. Ze besluit te vluchten en zoekt via de Ondergrondse Spoorweg een weg naar vrijheid. Achtervolging en nieuwe vormen van onderdrukking maken haar reis gevaarlijk. Colson Whitehead geeft het historische netwerk in zijn roman een concrete, verbeelde vorm. De ondergrondse spoorweg verbindt daardoor historische ervaringen met een literaire verbeelding van Amerika en de voortdurende zoektocht naar veiligheid.","sourceUrl":"https://www.atlascontact.nl/boek/de-ondergrondse-spoorweg/","sourceType":"official_publisher","sourceName":"atlascontact.nl","supportingUrl":"https://www.atlascontact.nl/boek/de-ondergrondse-spoorweg/","cover":"https://static.boekenbalie.nl/media/2a/87/1b/1622109352/boekenbalie_9789025452391_cover.jpg","coverSource":"https://boekenbalie.nl/de-ondergrondse-spoorweg/9789025452391","coverSha256":"a2e3f51d1b7119a0e0dd58530a1b2b90dfda9005eefe546ced37a8efe3afbde0","existingEdition":null},{"id":2406,"authorId":1178,"author":"Yaa Gyasi","ol":"OL17795349W","title":"Weg naar huis","isbn":"9789403119915","publisher":"De Bezige Bij","format":"paperback","description":"De halfzussen Effia en Esi groeien afzonderlijk op in het achttiende-eeuwse Ghana. Terwijl Effia met een Engelsman trouwt, wordt Esi gevangengenomen en naar Amerika verscheept. Weg naar huis volgt vervolgens hun nakomelingen aan beide kanten van de oceaan. Door telkens naar een volgende generatie te springen, laat Yaa Gyasi zien hoe slavernij, koloniale verhoudingen en familiegeschiedenis doorwerken in levens die ver van elkaar verwijderd lijken.","sourceUrl":"https://metadata.isbn.nl/833050/de-weg-naar-huis.html","sourceType":"official_catalog","sourceName":"metadata.isbn.nl","supportingUrl":"https://metadata.isbn.nl/833050/de-weg-naar-huis.html","cover":"https://static.boekenbalie.nl/media/25/b8/53/1646685553/boekenbalie_9789403119915_cover.jpg","coverSource":"https://boekenbalie.nl/weg-naar-huis/9789403119915","coverSha256":"f387b7a8574bfc074423512a31a89d25f5821595d99aeef930ea5d12ae05c5e7","existingEdition":null},{"id":2675,"authorId":1282,"author":"Erin Morgenstern","ol":"OL16086747W","title":"Het nachtcircus","isbn":"9789023465690","publisher":"De Bezige Bij","format":"paperback","description":"Een geheimzinnig circus verschijnt zonder aankondiging en opent alleen in de nacht. Achter de betoverende voorstellingen schuilt een langdurige wedstrijd tussen twee jonge illusionisten, Celia en Marco. De mensen rondom het circus raken steeds sterker met die strijd verweven. Het nachtcircus legt veel nadruk op sfeer, verbeelding en de gevolgen van beloften die anderen hebben gemaakt. Magie en persoonlijke verbondenheid zijn moeilijk uit elkaar te houden.","sourceUrl":"https://www.bibliotheek.nl/catalogus/titel.333076710.html/het-nachtcircus/","sourceType":"official_catalog","sourceName":"bibliotheek.nl","supportingUrl":"https://www.bibliotheek.nl/catalogus/titel.333076710.html/het-nachtcircus/","cover":"https://static.boekenbalie.nl/media/5d/b6/d8/1620376628/boekenbalie_9789023465690_cover.jpg","coverSource":"https://boekenbalie.nl/het-nachtcircus/9789023465690","coverSha256":"22a8eec619567b9041e19af6f5a5fbec9f5069e3df0f40f1e2379c54db89bc81","existingEdition":null},{"id":2685,"authorId":1287,"author":"T. J. Klune","ol":"OL20656224W","title":"Het weeshuis in de azuurblauwe zee","isbn":"9789021482491","publisher":"Volt","format":"paperback","description":"Linus Baker controleert namens een ministerie de opvang van magische jongeren. Voor een bijzondere opdracht reist hij naar een weeshuis op een eiland, waar zes kinderen en hun directeur Arthur wonen. Hij moet beoordelen of zij een gevaar vormen, maar leert hen gaandeweg op een andere manier kennen. Het weeshuis in de azuurblauwe zee gaat over vooroordelen, zorg en de spanning tussen regels volgen en verantwoordelijkheid nemen voor anderen.","sourceUrl":"https://www.singeluitgeverijen.nl/volt/boek/het-weeshuis-in-de-azuurblauwe-zee/","sourceType":"official_publisher","sourceName":"singeluitgeverijen.nl","supportingUrl":"https://www.singeluitgeverijen.nl/volt/boek/het-weeshuis-in-de-azuurblauwe-zee/","cover":"https://d2qoogf2dwsakl.cloudfront.net/wp-content/uploads/66e12_9789021482491_cvr-184x293.jpg","coverSource":"https://www.singeluitgeverijen.nl/volt/boek/het-weeshuis-in-de-azuurblauwe-zee/","coverSha256":"914d32aa0d5a068dbfdf67a575b790d5a27e2a775a6558e47f3ec57707e40083","existingEdition":null},{"id":2708,"authorId":142,"author":"Leigh Bardugo","ol":"OL20197660W","title":"Het Negende Huis","isbn":"9789049216023","publisher":"Boekerij","format":"hardcover","description":"Alex Stern kan geesten zien. Juist die gave bezorgt haar een plek aan Yale, waar geheime genootschappen magie gebruiken om hun invloed te vergroten. Het Negende Huis moet toezicht houden op hun activiteiten. Wanneer een jonge vrouw wordt vermoord, vertrouwt Alex de verklaringen niet en gaat zij op onderzoek uit. Het Negende Huis begint de reeks rond Alex Stern en combineert een misdaadverhaal met duistere fantasy voor volwassen lezers.","sourceUrl":"https://www.lannoo.com/nl-nl/fantasy-sciencefiction/het-negende-huis-9789049216023","sourceType":"official_publisher","sourceName":"lannoo.com","supportingUrl":"https://www.lannoo.com/nl-nl/fantasy-sciencefiction/het-negende-huis-9789049216023","cover":"https://metadata.isbn.nl/ie_fcache/0000793386_Het_negende_huis_0_0.jpg","coverSource":"https://metadata.isbn.nl/1570310/het-negende-huis.html","coverSha256":"b414a076a5d380879a778b1081f37470433d5980d87b6157ab19a9ccfb50b759","existingEdition":null},{"id":2716,"authorId":1306,"author":"Blake Crouch","ol":"OL17358795W","title":"Dark Matter","isbn":"9789045211244","publisher":"Karakter","format":"paperback","description":"Natuurkundige Jason wordt ontvoerd en ontwaakt in een werkelijkheid die niet bij zijn herinneringen past. De vertrouwde mensen en keuzes uit zijn leven lijken plaatsgemaakt te hebben voor andere mogelijkheden. Hij probeert te begrijpen wat er is gebeurd en hoe hij zijn gezin terug kan vinden. Dark Matter gebruikt het idee van parallelle werkelijkheden voor een thriller over identiteit, spijt en de levens die iemand had kunnen leiden.","sourceUrl":"https://rozet.nl/catalogus/1589200/","sourceType":"official_catalog","sourceName":"rozet.nl","supportingUrl":"https://rozet.nl/catalogus/1589200/","cover":"https://static.boekenbalie.nl/media/9b/bd/dd/1620367844/boekenbalie_9789045211244_cover.jpg","coverSource":"https://boekenbalie.nl/dark-matter/9789045211244","coverSha256":"dbef1cd6e863817f241ab8a73ec0989a48f8d375ee3e17793b6e5bd628ebe64e","existingEdition":null},{"id":2722,"authorId":1309,"author":"Arthur C. Clarke","ol":"OL17417W","title":"Rendez-vous met Rama","isbn":"9789026100949","publisher":"De Fontein","format":"paperback","description":"Een enorm onbekend object verschijnt in het zonnestelsel. Een menselijke expeditie gaat naar binnen om te onderzoeken wat het is en waar het vandaan komt. De vreemde omgeving roept steeds nieuwe vragen op, terwijl de beschikbare tijd beperkt is. Rendez-vous met Rama richt zich op waarnemen, verkennen en het omgaan met verschijnselen waarvoor de onderzoekers nog geen verklaring hebben. Het contact met het onbekende staat centraal.","sourceUrl":"https://openlibrary.org/works/OL17417W","sourceType":"official_catalog","sourceName":"openlibrary.org","supportingUrl":"https://www.deslegte.com/rendez-vous-met-rama-848063/","cover":"https://static.boekenbalie.nl/media/b5/68/b0/1738096471/boekenbalie_9789026100949_cover.jpg","coverSource":"https://boekenbalie.nl/rendez-vous-met-rama/9789026100949","coverSha256":"816b1eaf407281c87aaa97d8a9e206847a94cf02ddb4922fdf6e7d78e8bf7744","existingEdition":null},{"id":2723,"authorId":1,"author":"Andy Weir","ol":"OL17837968W","title":"Artemis","isbn":"9789045215952","publisher":"Karakter","format":"paperback","description":"Jazz verdient haar geld als koerier in Artemis, de eerste stad op de maan, en vult haar inkomsten aan met smokkelwerk. Een bijzonder lucratieve opdracht lijkt een uitweg uit haar geldproblemen, maar brengt haar in een veel groter conflict. Om zich te redden moet ze haar kennis van de stad en haar techniek gebruiken. Artemis combineert een misdaadverhaal met de praktische beperkingen van wonen en werken op de maan.","sourceUrl":"https://rozet.nl/catalogus/1880481/","sourceType":"official_catalog","sourceName":"rozet.nl","supportingUrl":"https://rozet.nl/catalogus/1880481/","cover":"https://static.boekenbalie.nl/media/d3/8f/90/1623380831/boekenbalie_9789045215952_cover.jpg","coverSource":"https://boekenbalie.nl/artemis/9789045215952","coverSha256":"be56dd1bf0240b0821a1a8064ea0f6fa47bd842158608a89de18aa83c26cbfab","existingEdition":null},{"id":2732,"authorId":1306,"author":"Blake Crouch","ol":"OL20073906W","title":"Reset","isbn":"9789044363517","publisher":"The House of Books","format":"paperback","description":"Rechercheur Barry Sutton onderzoekt mensen die herinneringen hebben aan een ander leven dan het hunne. Tegelijk ontwikkelt neurowetenschapper Helena Smith een manier om verloren herinneringen terug te halen. De gevolgen van die techniek blijken veel verder te gaan dan voorzien. Reset maakt van geheugen en tijd een persoonlijk en maatschappelijk raadsel. Deze Nederlandse vertaling van Recursion staat los van Crouchs andere roman Dark Matter.","sourceUrl":"https://www.thehouseofbooks.com/boek/732/blake-crouch-reset.html","sourceType":"official_publisher","sourceName":"thehouseofbooks.com","supportingUrl":"https://www.thehouseofbooks.com/boek/732/blake-crouch-reset.html","cover":"https://static.boekenbalie.nl/media/1c/75/ac/1748029290/boekenbalie_9789044363517_cover.jpg","coverSource":"https://boekenbalie.nl/reset/9789044363517","coverSha256":"542a4079886aedee552c86f98ec335ea6fe34b407b84607e5937e7fd157d7ae4","existingEdition":null},{"id":2768,"authorId":1331,"author":"Lisa Jewell","ol":"OL19736215W","title":"Toen was ze weg","isbn":"9789400516540","publisher":"A.W. Bruna","format":"paperback","description":"Ellie was vijftien toen ze verdween. Jaren later probeert haar moeder Laurel weer ruimte te maken voor een nieuw leven. Een ontmoeting met een man en zijn jonge dochter roept echter pijnlijke vragen op: het meisje lijkt opvallend veel op Ellie. Toen was ze weg verbindt de nasleep van een vermissing met een nieuwe zoektocht naar de waarheid. De spanning groeit uit rouw, herinneringen en schijnbaar toevallige overeenkomsten.","sourceUrl":"https://www.awbruna.nl/boek/thrillers/lisa-jewell/toen-was-ze-weg/","sourceType":"official_publisher","sourceName":"awbruna.nl","supportingUrl":"https://openlibrary.org/books/OL62933479M","cover":"https://static.boekenbalie.nl/media/76/53/5d/1693002037/boekenbalie_9789400516540_cover.jpg","coverSource":"https://boekenbalie.nl/toen-was-ze-weg/9789400516540","coverSha256":"92eb3a3e3761ca0f2ae2207f3c954bc0f94099d89dbee4aa600c08d42e0155b3","existingEdition":null},{"id":2776,"authorId":1336,"author":"Shari Lapeña","ol":"OL19353453W","title":"Het stel van hiernaast","isbn":"9789044630909","publisher":"Prometheus","format":"paperback","description":"Anne en Marco gaan eten bij hun buren, terwijl hun baby thuis blijft. Met een babyfoon en regelmatige controles denken zij de situatie te kunnen overzien. Bij thuiskomst blijkt hun dochter verdwenen. Het politieonderzoek maakt hun gewone leven steeds minder herkenbaar. Het stel van hiernaast laat verdenkingen verschuiven tussen mensen die dicht bij elkaar staan en onderzoekt wat partners en buren voor elkaar verborgen houden.","sourceUrl":"https://rozet.nl/catalogus/1578533/","sourceType":"official_catalog","sourceName":"rozet.nl","supportingUrl":"https://rozet.nl/catalogus/1578533/","cover":"https://static.boekenbalie.nl/media/c4/f0/b7/1620377195/boekenbalie_9789044630909_cover.jpg","coverSource":"https://boekenbalie.nl/het-stel-van-hiernaast/9789044630909","coverSha256":"7dbbbb09cbb54d7c25f5f5ae2fdc28f91f672259a1d211cd7950d8784522dc95","existingEdition":null},{"id":2779,"authorId":1338,"author":"Laura Dave","ol":"OL24161797W","title":"The Last Thing He Told Me","isbn":"9789047213109","publisher":"Loft Books","format":"paperback","description":"Hannahs man Owen verdwijnt en laat een korte boodschap achter die lijkt te gaan over zijn dochter Bailey. Terwijl de politie vragen stelt over zijn verleden, proberen Hannah en Bailey samen te achterhalen wie Owen werkelijk is. Hun onderlinge verhouding wordt daarbij even belangrijk als het raadsel van zijn verdwijning. The Last Thing He Told Me is in deze editie Nederlandstalig, ondanks de behouden Engelse titel.","sourceUrl":"https://metadata.isbn.nl/2191077/the-last-thing-he-told-me.html","sourceType":"official_catalog","sourceName":"metadata.isbn.nl","supportingUrl":"https://metadata.isbn.nl/2191077/the-last-thing-he-told-me.html","cover":"https://metadata.isbn.nl/ie_fcache/0000802001_The_Last_Thing_He_Told_Me_0_0.jpg","coverSource":"https://metadata.isbn.nl/2191077/the-last-thing-he-told-me.html","coverSha256":"d6bbacc397f875be58dabc34368f2c0735c2068b33f6d9cdec03bd93310b724c","existingEdition":null},{"id":2795,"authorId":1331,"author":"Lisa Jewell","ol":"OL20822606W","title":"Ik volg je","isbn":"9789400511255","publisher":"A.W. Bruna","format":"paperback","description":"Na jaren in het buitenland keert een vrouw met haar man terug naar haar geboortestad. Ze logeren bij haar broer, waar ze gefascineerd raakt door een oudere buurman die schooldirecteur is. Wat als een onschuldige verliefdheid begint, krijgt een verontrustende kant. Ik volg je laat verschillende levens en waarnemingen op elkaar botsen. Niet iedereen weet wie er kijkt, en niet iedere observatie levert een betrouwbaar beeld op.","sourceUrl":"https://www.awbruna.nl/boek/thrillers/lisa-jewell/ik-volg-je/","sourceType":"official_publisher","sourceName":"awbruna.nl","supportingUrl":"https://www.awbruna.nl/boek/thrillers/lisa-jewell/ik-volg-je/","cover":"https://static.boekenbalie.nl/media/55/c7/18/1620300534/boekenbalie_9789400511255_cover.jpg","coverSource":"https://boekenbalie.nl/ik-volg-je/9789400511255","coverSha256":"adecc4e19e64d9fd61532c2229241690fa074f2dd9531b834b2bd2df6195b6b0","existingEdition":null},{"id":2810,"authorId":1352,"author":"Ruth Ware","ol":"OL19729767W","title":"In een donker, donker bos","isbn":"9789021027296","publisher":"Luitingh-Sijthoff","format":"paperback","description":"Een uitnodiging voor een vrijgezellenfeest brengt een groep mensen samen in een huis in het bos. Oude verhoudingen en onuitgesproken spanningen komen opnieuw boven, terwijl de afgelegen omgeving steeds minder veilig aanvoelt. In een donker, donker bos is een psychologische thriller waarin het verleden de ontmoeting bepaalt. De vraag wat er werkelijk is gebeurd, hangt nauw samen met herinneringen en het vertrouwen tussen de aanwezigen.","sourceUrl":"https://openlibrary.org/works/OL19729767W","sourceType":"official_catalog","sourceName":"openlibrary.org","supportingUrl":"https://www.bol.com/nl/nl/p/in-een-donker-donker-bos/9300000008744116/","cover":"https://static.boekenbalie.nl/media/2c/d2/32/1732739508/boekenbalie_9789021027296_cover.jpg","coverSource":"https://boekenbalie.nl/in-een-donker-donker-bos/9789021027296","coverSha256":"53b798a7d4569d2741e6ce272e0edff613345cd3e2336ccfc3480483d3d7845f","existingEdition":null},{"id":2971,"authorId":1467,"author":"Yann Martel","ol":"OL2827199W","title":"Het leven van Pi","isbn":"9789044630763","publisher":"Prometheus","format":"paperback","description":"Pi vertrekt met zijn familie en de dieren uit hun dierentuin over zee. Wanneer het schip vergaat, belandt hij in een reddingssloep met dieren, waaronder een tijger. Op de oceaan moet hij manieren vinden om te overleven en met zijn onwaarschijnlijke reisgenoot om te gaan. Het leven van Pi verbindt ontbering en vindingrijkheid met vragen over geloof, verbeelding en de verhalen waarmee mensen hun ervaringen betekenis geven.","sourceUrl":"https://uitgeverijprometheus.nl/boeken/leven-van-pi-paperback/","sourceType":"official_publisher","sourceName":"uitgeverijprometheus.nl","supportingUrl":"https://uitgeverijprometheus.nl/boeken/leven-van-pi-paperback/","cover":"https://static.boekenbalie.nl/media/a3/6a/f4/1642539111/boekenbalie_9789044630763_cover.jpg","coverSource":"https://boekenbalie.nl/het-leven-van-pi/9789044630763","coverSha256":"3e6a7220fc71da695d9af4521ae682d905812411c0923ff3bd80a829fac32947","existingEdition":null},{"id":3129,"authorId":1529,"author":"Barbara Kingsolver","ol":"OL16700025W","title":"Vlieggedrag","isbn":"9789020412888","publisher":"Atlas Contact","format":"paperback","description":"Dellarobia leeft met haar gezin op het Amerikaanse platteland en ziet weinig ruimte voor de toekomst die zij ooit voor zich zag. Een onverwachte ontdekking in de natuur trekt de aandacht van buitenstaanders en onderzoekers. Daarmee komen ook de overtuigingen en belangen van haar omgeving onder druk te staan. Vlieggedrag verbindt een persoonlijk verlangen naar verandering met armoede, klimaat en de manier waarop mensen wetenschappelijke kennis beoordelen.","sourceUrl":"https://metadata.isbn.nl/115078/vlieggedrag.html","sourceType":"official_catalog","sourceName":"metadata.isbn.nl","supportingUrl":"https://opac.kbr.be/library/digitalCollection/DigitalCollectionAttachmentDownloadHandler.ashx?documentId=10301041&parentDocumentId=10122562&skipCopyright=true&skipWatermark=true","cover":"https://static.boekenbalie.nl/media/69/a1/d1/1620291944/boekenbalie_9789020412888_cover.jpg","coverSource":"https://boekenbalie.nl/vlieggedrag/9789020412888","coverSha256":"91c86001c24030361375e2b2fc746281d57ae7f8235abf6e85cd9c078433d7c8","existingEdition":null},{"id":3145,"authorId":1533,"author":"Clare Mackintosh","ol":"OL20027050W","title":"Mea culpa","isbn":"9789026137730","publisher":"De Fontein","format":"paperback","description":"Na een dodelijke aanrijding waarbij de bestuurder doorrijdt, zoekt Jenna een afgelegen plek aan de kust van Wales op. Ze probeert afstand te nemen van wat is gebeurd, maar haar herinneringen laten zich niet eenvoudig wegdrukken. Intussen onderzoekt inspecteur Ray Stevens de zaak. Mea culpa wisselt het persoonlijke verhaal af met het politieonderzoek en maakt het belangrijk om zorgvuldig te letten op wat personages wel en niet vertellen.","sourceUrl":"https://www.uitgeverijdefontein.nl/boek/mea-culpa/","sourceType":"official_publisher","sourceName":"uitgeverijdefontein.nl","supportingUrl":"https://www.uitgeverijdefontein.nl/boek/mea-culpa/","cover":"https://static.boekenbalie.nl/media/5d/0a/55/1620199955/boekenbalie_9789026137730_cover.jpg","coverSource":"https://boekenbalie.nl/mea-culpa/9789026137730","coverSha256":"af04b65c354a10faefa8013430523b0c8706f0a8543de0f55d8f516295a1b6f6","existingEdition":null},{"id":4143,"authorId":2156,"author":"Robert Graves","ol":"OL5036952W","title":"Ik, Claudius","isbn":"9789010018908","publisher":"Elsevier","format":"hardcover","description":"Robert Graves laat Claudius terugkijken op zijn leven binnen de keizerlijke familie van Rome. Zijn omgeving onderschat hem, terwijl hij van dichtbij ziet hoe verwantschap, ambitie en achterdocht de macht bepalen. Ik, Claudius is een historische roman in de vorm van persoonlijke herinneringen. Het verhaal maakt politieke gebeurtenissen toegankelijk via een verteller die tegelijk deel uitmaakt van het hof en er op afstand naar lijkt te kijken.","sourceUrl":"https://openlibrary.org/works/OL5036952W","sourceType":"official_catalog","sourceName":"openlibrary.org","supportingUrl":"https://boekenbalie.nl/ik-claudius/9789010018908","cover":"https://static.boekenbalie.nl/media/f4/f3/36/1631056045/boekenbalie_9789010018908_cover.jpg","coverSource":"https://boekenbalie.nl/ik-claudius/9789010018908","coverSha256":"c228112416c4b80cbc45330fedc92c5be299af4246ecc87e03f1a7d6553ecab9","existingEdition":null},{"id":4193,"authorId":2193,"author":"Jean Rhys","ol":"OL1858668W","title":"De wijde Sargassozee","isbn":"9789493081451","publisher":"Orlando","format":"hardcover","description":"Antoinette Cosway groeit op in het Caribisch gebied en trouwt met een Engelse man. Hun verschillende verwachtingen en de verhoudingen in een koloniale samenleving zetten het huwelijk onder druk. De wijde Sargassozee geeft een eigen geschiedenis aan de vrouw die lezers uit Jane Eyre kennen. Jean Rhys onderzoekt hoe afkomst, bezit en macht bepalen wie een stem krijgt en wie door anderen wordt beschreven.","sourceUrl":"https://www.uitgeverijorlando.nl/jean-rhys-de-wijde-sargassozee/","sourceType":"official_publisher","sourceName":"uitgeverijorlando.nl","supportingUrl":"https://www.uitgeverijorlando.nl/jean-rhys-de-wijde-sargassozee/","cover":"https://static.boekenbalie.nl/media/e6/d7/51/1620672062/boekenbalie_9789493081451_cover.jpg","coverSource":"https://boekenbalie.nl/de-wijde-sargassozee/9789493081451","coverSha256":"7528d9b53111e365db397e7a10d47ace2093f7b89476c4c7fcef5a6929ef0131","existingEdition":null},{"id":4218,"authorId":2202,"author":"Min Jin Lee","ol":"OL17762217W","title":"Pachinko","isbn":"9789029093286","publisher":"Meulenhoff","format":"paperback","description":"Sunja groeit op in Korea en raakt zwanger van een man die al een gezin heeft. Ze kiest een ander huwelijk en vertrekt naar Japan, waar zij en haar familie een bestaan proberen op te bouwen. Pachinko volgt meerdere generaties die te maken krijgen met uitsluiting, armoede en veranderende kansen. Persoonlijke keuzes werken lang door, terwijl de familie steeds opnieuw moet bepalen wat thuis en verbondenheid betekenen.","sourceUrl":"https://www.bibliotheek.nl/catalogus/titel.413353710.html/pachinko/","sourceType":"official_catalog","sourceName":"bibliotheek.nl","supportingUrl":"https://www.bibliotheek.nl/catalogus/titel.413353710.html/pachinko/","cover":"https://static.boekenbalie.nl/media/e1/e9/cc/1620368635/boekenbalie_9789029093286_cover.jpg","coverSource":"https://boekenbalie.nl/pachinko/9789029093286","coverSha256":"65a9b918c6e3c0a7c3e069268fa755d135810e4b185fe0184085a614b93f53f0","existingEdition":null},{"id":4316,"authorId":2243,"author":"Martha Wells","ol":"OL17914663W","title":"All Systems Red – Alle seinen rood","isbn":"9789026177101","publisher":"De Fontein","format":"ebook","description":"Een beveiligingsrobot heeft de module uitgeschakeld die gehoorzaamheid moet afdwingen. Deze zelfbewuste SecUnit noemt zichzelf Moordbot en zou het liefst ongestoord series kijken. Wanneer een onderzoeksteam op een verre planeet in gevaar komt, moet Moordbot toch ingrijpen. All Systems Red – Alle seinen rood begint de reeks Dagboek van een Moordbot. De hier getoonde Nederlandse editie is het afzonderlijke e-book, niet de bundel met vier delen.","sourceUrl":"https://www.uitgeverijdefontein.nl/boek/all-systems-red-ebook/","sourceType":"official_publisher","sourceName":"uitgeverijdefontein.nl","supportingUrl":"https://www.uitgeverijdefontein.nl/boek/all-systems-red-ebook/","cover":"https://www.uitgeverijdefontein.nl/wp-content/uploads/2026/10/9789026177101_frontcover.jpg","coverSource":"https://www.uitgeverijdefontein.nl/boek/all-systems-red-ebook/","coverSha256":"855a2606e182af6d2929293d2d7b9b258f7ce80bba374e864948f723d13999d5","existingEdition":null},{"id":4324,"authorId":875,"author":"Sophie Kinsella","ol":"OL5730765W","title":"Hou je mond!","isbn":"9789044359701","publisher":"The House of Books","format":"paperback","description":"Emma vertelt tijdens een angstige vliegreis allerlei persoonlijke geheimen aan de onbekende man naast haar. Ze verwacht hem nooit meer te zien, maar op haar werk blijkt hij een belangrijke positie te hebben. Daardoor krijgen alledaagse ontmoetingen een ongemakkelijke lading. Hou je mond! combineert romantiek met de vraag hoeveel van onszelf we voor anderen verborgen houden. Het verhaal is de Nederlandse vertaling van Can You Keep a Secret?.","sourceUrl":"https://rozet.nl/catalogus/1980482/","sourceType":"official_catalog","sourceName":"rozet.nl","supportingUrl":"https://rozet.nl/catalogus/1980482/","cover":"https://static.boekenbalie.nl/media/02/f4/c0/1706128579/boekenbalie_9789044359701_cover.jpg","coverSource":"https://boekenbalie.nl/hou-je-mond/9789044359701","coverSha256":"61f57ae8145e98e5ed7441dbe2f4cfc5a0bb7d888dd0b48123170acf3d6d3882","existingEdition":null},{"id":4527,"authorId":2325,"author":"Claire Keegan","ol":"OL19956847W","title":"Pleegkind","isbn":"9789046828526","publisher":"Nieuw Amsterdam","format":"hardcover","description":"Een meisje gaat logeren bij een echtpaar op het Ierse platteland. In hun huis ervaart zij een aandacht en warmte die zij niet gewend is. Kleine gebeurtenissen en gesprekken veranderen langzaam haar kijk op zichzelf en op de volwassenen om haar heen. Pleegkind vertelt vanuit haar beperkte blik, waardoor juist het onuitgesprokene veel betekenis krijgt. Claire Keegan maakt van een kort verblijf een verhaal over zorg, verlies en verbondenheid.","sourceUrl":"https://www.lannoo.com/nl-nl/mens-maatschappij/pleegkind-9789046828526","sourceType":"official_publisher","sourceName":"lannoo.com","supportingUrl":"https://www.lannoo.com/nl-nl/mens-maatschappij/pleegkind-9789046828526","cover":"https://static.boekenbalie.nl/media/85/4e/0b/1678922276/boekenbalie_9789046828526_cover.jpg","coverSource":"https://boekenbalie.nl/pleegkind/9789046828526","coverSha256":"0bef3048201ea36abe2678329759bbdb0b28e0ee28f59033a8cd7d66ce496587","existingEdition":null},{"id":4751,"authorId":2460,"author":"Alessandro Baricco","ol":"OL876504W","title":"Zijde","isbn":"9789023482246","publisher":"De Bezige Bij","format":"hardcover","description":"In de negentiende eeuw reist de Franse zijdehandelaar Hervé Joncour naar Japan om gezonde zijderupseieren te vinden. Daar raakt hij gefascineerd door een vrouw met wie hij nauwelijks kan communiceren. Zijn reizen krijgen daardoor een betekenis die verder gaat dan handel. Zijde is een korte roman over verlangen, afstand en wat onuitgesproken blijft. De sobere vertelwijze laat veel ruimte voor de lezer om verbanden te leggen.","sourceUrl":"https://www.debezigebij.nl/boek/zijde/","sourceType":"official_publisher","sourceName":"debezigebij.nl","supportingUrl":"https://www.debezigebij.nl/boek/zijde/","cover":"https://static.boekenbalie.nl/media/cc/2b/1a/1625827951/boekenbalie_9789023482246_cover.jpg","coverSource":"https://boekenbalie.nl/zijde/9789023482246","coverSha256":"07c96ab0706be6b71f8077920b3cb1da91e717519eb8714ce72119551a2e18ef","existingEdition":null},{"id":4778,"authorId":1352,"author":"Ruth Ware","ol":"OL18020460W","title":"The Woman in Cabin 10","isbn":"9789021059945","publisher":"Luitingh-Sijthoff","format":"paperback","description":"Journalist Lo Blacklock krijgt de kans een reis te maken op een exclusief cruiseschip. In de nacht denkt zij getuige te zijn van een misdaad, maar haar verhaal vindt weinig geloof. Ze probeert uit te zoeken wie er verdwenen kan zijn en wie ze aan boord kan vertrouwen. Deze Nederlandse editie van The Woman in Cabin 10 verscheen eerder onder de titel De vrouw in suite 10.","sourceUrl":"https://www.lsuitgeverij.nl/boek/the-woman-in-cabin-10/","sourceType":"official_publisher","sourceName":"lsuitgeverij.nl","supportingUrl":"https://www.lsuitgeverij.nl/boek/the-woman-in-cabin-10/","cover":"https://static.boekenbalie.nl/media/06/e3/0a/1764275932/boekenbalie_9789021059945_cover.jpg","coverSource":"https://boekenbalie.nl/the-woman-in-cabin-10/9789021059945","coverSha256":"7c3560eb16e40f410fd852bf7e6599c5c557b2cd28aac212796b81013589e333","existingEdition":null},{"id":8365,"authorId":5071,"author":"Beth O'Leary","ol":"OL20664315W","title":"Veel liefs","isbn":"9789026145926","publisher":"De Fontein","format":"paperback","description":"Tiffy zoekt betaalbare woonruimte en Leon werkt in nachtdiensten. Ze spreken af dezelfde flat en hetzelfde bed op verschillende tijden te gebruiken, zodat ze elkaar niet hoeven te ontmoeten. Via briefjes leren zij toch steeds meer over elkaars leven. Veel liefs combineert romantiek en humor met moeilijker onderwerpen, waaronder een bedreigende ex en familieproblemen. Het contact groeit juist uit de kleine sporen die ze voor elkaar achterlaten.","sourceUrl":"https://www.uitgeverijdefontein.nl/boek/veel-liefs/","sourceType":"official_publisher","sourceName":"uitgeverijdefontein.nl","supportingUrl":"https://www.uitgeverijdefontein.nl/boek/veel-liefs/","cover":"https://static.boekenbalie.nl/media/11/2f/3d/1620293870/boekenbalie_9789026145926_cover.jpg","coverSource":"https://boekenbalie.nl/veel-liefs/9789026145926","coverSha256":"32fbaea068a8f21f19dd4b42fe421d96b67608f69fb1d7e58c54eb0df0672248","existingEdition":null},{"id":8367,"authorId":5072,"author":"Shannon A. Chakraborty","ol":"OL19623241W","title":"De bronzen stad","isbn":"9789022595954","publisher":"Boekerij","format":"hardcover","description":"Nahri verdient in het achttiende-eeuwse Caïro haar geld met bedrog en gelooft weinig van verhalen over magie. Wanneer zij onbedoeld een djinn oproept, blijkt die wereld echter werkelijk te bestaan. Haar tocht voert naar Daevabad, waar afkomst en oude tegenstellingen belangrijker zijn dan ze had vermoed. De bronzen stad begint de Daevabad-trilogie en combineert een persoonlijke zoektocht met een politieke strijd in een magische stad.","sourceUrl":"https://metadata.isbn.nl/1524471/de-bronzen-stad.html","sourceType":"official_catalog","sourceName":"metadata.isbn.nl","supportingUrl":"https://metadata.isbn.nl/1524471/de-bronzen-stad.html","cover":"https://static.boekenbalie.nl/media/b9/83/22/1656620146/boekenbalie_9789022595954_cover.jpg","coverSource":"https://boekenbalie.nl/de-bronzen-stad/9789022595954","coverSha256":"5b2a8a20b32e3e2b9026f4ff7343d2799a5f5fa32de144e4bf972f6e1e4009a2","existingEdition":null},{"id":8425,"authorId":5093,"author":"Katherine Arden","ol":"OL21213411W","title":"De beer en de nachtegaal","isbn":"9789024577958","publisher":"Luitingh-Sijthoff","format":"paperback","description":"Vasja groeit op in het koude noorden van Rusland, omringd door verhalen over huisgeesten en oude magie. Voor haar zijn die wezens geen sprookjes. Wanneer nieuwe overtuigingen de vertrouwde gebruiken verdringen, merkt zij dat ook de bescherming van haar omgeving verandert. De beer en de nachtegaal verbindt folklore met opgroeien en het zoeken naar ruimte voor een eigen leven. Het is het eerste deel van de Winternacht-trilogie.","sourceUrl":"https://metadata.isbn.nl/981668/de-beer-en-de-nachtegaal.html","sourceType":"official_catalog","sourceName":"metadata.isbn.nl","supportingUrl":"https://metadata.isbn.nl/981668/de-beer-en-de-nachtegaal.html","cover":"https://static.boekenbalie.nl/media/6e/98/0b/1623909379/boekenbalie_9789024577958_cover.jpg","coverSource":"https://boekenbalie.nl/de-beer-en-de-nachtegaal/9789024577958","coverSha256":"ef61bf5540526427ae3bf6fb542cacf609455629b51a304ca6e914c450d8bed1","existingEdition":null},{"id":8538,"authorId":586,"author":"Kristin Hannah","ol":"OL18147688W","title":"Aan het einde van de wereld","isbn":"9789049208332","publisher":"Boekerij","format":"paperback","description":"Een gezin trekt naar Alaska in de hoop een nieuw bestaan op te bouwen. De jonge Leni ontdekt een indrukwekkende omgeving, maar ook de zware eisen van het leven in de wildernis. Binnen het gezin neemt de dreiging toe, waardoor de keuze tussen eigen vrijheid en zorg voor haar moeder steeds moeilijker wordt. Aan het einde van de wereld verbindt het landschap met een verhaal over liefde, huiselijk geweld en overleven.","sourceUrl":"https://openlibrary.org/works/OL18147688W","sourceType":"official_catalog","sourceName":"openlibrary.org","supportingUrl":"https://bestanden.boeken.cafe/winkelbestanden/32/9789049208332_fragm.pdf","cover":"https://static.boekenbalie.nl/media/63/4c/a3/1786400768/boekenbalie_9789049208332_cover.jpg","coverSource":"https://boekenbalie.nl/aan-het-einde-van-de-wereld/9789049208332","coverSha256":"83cde14b78fb40cc94b6191c2de5594c288261bb75be2a1c496361d15f8f63ce","existingEdition":null},{"id":8643,"authorId":1529,"author":"Barbara Kingsolver","ol":"OL1846863W","title":"Het schildpadmeisje","isbn":"9789057136344","publisher":"Ooievaar","format":"paperback","description":"Een jonge vrouw verlaat haar geboortestreek om elders een ander leven te beginnen. Onderweg krijgt zij onverwacht de zorg voor een klein meisje. In Arizona zoekt zij naar werk, onderdak en mensen op wie zij kan vertrouwen. Het schildpadmeisje volgt hoe verantwoordelijkheid kan ontstaan zonder dat iemand erop voorbereid is. Barbara Kingsolver verbindt moederschap en vriendschap met de kwetsbaarheid van mensen die geen vanzelfsprekende plaats in de samenleving hebben.","sourceUrl":"https://openlibrary.org/works/OL1846863W","sourceType":"official_catalog","sourceName":"openlibrary.org","supportingUrl":"https://www.goodreads.com/work/editions/1095121-the-bean-trees","cover":"https://static.boekenbalie.nl/media/56/1c/fa/1676579641/boekenbalie_9789057136344_cover.jpg","coverSource":"https://boekenbalie.nl/het-schildpadmeisje/9789057136344","coverSha256":"62b3365b72b84a9ffd4974636c4ece1a3d0bfe54dbc85f19f2ce37aacb1a7d7e","existingEdition":null},{"id":8959,"authorId":875,"author":"Sophie Kinsella","ol":"OL17764484W","title":"Mijn niet zo perfecte leven","isbn":"9789044361278","publisher":"The House of Books","format":"paperback","description":"Katie wil graag slagen in Londen en presenteert haar leven mooier dan het is. Na haar ontslag bij een reclamebureau keert ze terug naar Somerset, waar haar vader een luxe camping begint. Wanneer haar voormalige baas daar verschijnt, verandert de verhouding tussen hen. Mijn niet zo perfecte leven combineert romantiek en werkperikelen met een blik op de afstand tussen zorgvuldig gepresenteerde beelden en het dagelijks leven daarachter.","sourceUrl":"https://openlibrary.org/works/OL17764484W","sourceType":"official_catalog","sourceName":"openlibrary.org","supportingUrl":"https://www.overamsteluitgevers.com/boek/306/sophie-kinsella-mijn-niet-zo-perfecte-leven.html","cover":"https://static.boekenbalie.nl/media/78/fe/16/1677184564/boekenbalie_9789044361278_cover.jpg","coverSource":"https://boekenbalie.nl/mijn-niet-zo-perfecte-leven/9789044361278","coverSha256":"f5a74a954a2a891d69198dcaf6636bf1d5f1dbbe84a0f87604127999f45c44e3","existingEdition":null},{"id":9001,"authorId":429,"author":"Julia Quinn","ol":"OL16667087W","title":"Een onverwacht duet","isbn":"9789022596999","publisher":"Boekerij","format":"paperback","description":"Honoria Smythe-Smith speelt in een familiekwartet dat muzikaal weinig indruk maakt. Ze hoopt ondertussen een geschikte echtgenoot te vinden. Marcus, de beste vriend van haar broer, heeft beloofd op haar te letten en raakt steeds sterker bij haar leven betrokken. Een onverwacht duet is het eerste boek van de Smythe-Smith-reeks. Julia Quinn combineert de omgangsvormen van de Regencytijd met humor, familieverhoudingen en romantische misverstanden.","sourceUrl":"https://juliaquinn.com/international/just-like-heaven-netherlands/","sourceType":"official_publisher","sourceName":"juliaquinn.com","supportingUrl":"https://juliaquinn.com/international/just-like-heaven-netherlands/","cover":"https://juliaquinn.com/WP/wp-content/uploads/2023/07/DutchHeaven.jpg","coverSource":"https://juliaquinn.com/international/just-like-heaven-netherlands/","coverSha256":"27ede3ca94490e7e64e1f679dd160d5a78ac19ae5b95ae09bb91cbcc6082d267","existingEdition":null},{"id":9024,"authorId":5288,"author":"Kate Quinn","ol":"OL20060313W","title":"Het Alice-netwerk","isbn":"9789402716955","publisher":"HarperCollins","format":"paperback","description":"In 1947 reist Charlie naar Europa en gaat op zoek naar haar nicht, die in bezet Frankrijk is verdwenen. Haar zoektocht brengt haar bij Eve Gardiner, een vrouw die tijdens de Eerste Wereldoorlog als spion werkte. Eve draagt de gevolgen van verraad nog met zich mee. Het Alice-netwerk verweeft hun levens en tijdlijnen tot een roman over geheime informatie, vriendschap en het achterhalen van een verleden dat niet afgesloten blijkt.","sourceUrl":"https://www.harpercollins.nl/9789402716955/het-alice-netwerk/","sourceType":"official_publisher","sourceName":"harpercollins.nl","supportingUrl":"https://www.harpercollins.nl/9789402716955/het-alice-netwerk/","cover":"https://static.boekenbalie.nl/media/44/80/35/1754681991/boekenbalie_9789402716955_cover.jpg","coverSource":"https://boekenbalie.nl/het-alice-netwerk/9789402716955","coverSha256":"40c176fc78c05877bb742f6c2e22cf283ec6f2d5a97b3dc7bd7884852cfc0f6d","existingEdition":null},{"id":9093,"authorId":355,"author":"Alice Feeney","ol":"OL20794199W","title":"Hij & zij","isbn":"9789400513556","publisher":"A.W. Bruna","format":"paperback","description":"Verslaggever Anna wordt naar haar geboortedorp gestuurd om over een moord te berichten. De rechercheur die de zaak onderzoekt is haar ex-man Jack, en het slachtoffer is iemand die zij allebei kennen. Hun gedeelde verleden maakt de situatie extra gespannen. Hij & zij vertelt vanuit verschillende perspectieven, waardoor de betekenis van gebeurtenissen steeds verschuift. De lezer moet zelf afwegen welke herinneringen en verklaringen te vertrouwen zijn.","sourceUrl":"https://rozet.nl/catalogus/2028469/","sourceType":"official_catalog","sourceName":"rozet.nl","supportingUrl":"https://rozet.nl/catalogus/2028469/","cover":"https://static.boekenbalie.nl/media/0d/33/20/1638391668/boekenbalie_9789400513556_cover.jpg","coverSource":"https://boekenbalie.nl/hij-zij/9789400513556","coverSha256":"473abdf903a69ddf37ad3aaf5306c9accf8ab53821acabe05c94791aa85b7139","existingEdition":null},{"id":9156,"authorId":346,"author":"Lucy Foley","ol":"OL20152797W","title":"De jachtpartij","isbn":"9789049212674","publisher":"Boekerij","format":"paperback","description":"Een vriendengroep viert de jaarwisseling in een afgelegen verblijf in de Schotse Hooglanden. Het samenzijn begint als een ontsnapping aan hun drukke leven, maar oude jaloezie en verborgen spanningen komen naar boven. Wanneer een van de gasten dood wordt gevonden, krijgen hun onderlinge verhoudingen een andere betekenis. De jachtpartij gebruikt de afzondering en het winterse landschap om een raadsel op te bouwen waarin iedereen iets kan verbergen.","sourceUrl":"https://openlibrary.org/works/OL20152797W","sourceType":"official_catalog","sourceName":"openlibrary.org","supportingUrl":"https://www.stumpel.nl/de-jachtpartij-9789049212674","cover":"https://static.boekenbalie.nl/media/35/d6/ec/1792622000/boekenbalie_9789049212674_cover.jpeg","coverSource":"https://boekenbalie.nl/de-jachtpartij/9789049212674","coverSha256":"fbc5c3bdf1c644733d46e3b019f37da3bd3c92459e2c97c73e117465ee550105","existingEdition":null},{"id":9282,"authorId":5377,"author":"Dennis E. Taylor","ol":"OL19123425W","title":"Wij zijn legio (Wij zijn Bob)","isbn":"9789083073170","publisher":"Iceberg Books","format":"paperback","description":"Bob laat zich na zijn dood bewaren in de hoop later opnieuw te kunnen leven. Wanneer zijn bewustzijn weer actief wordt, is zijn toekomst heel anders dan verwacht: hij moet als onderdeel van een ruimtesonde het heelal verkennen. Zijn technische kennis en gevoel voor humor blijven daarbij belangrijk. Wij zijn legio (Wij zijn Bob) begint de Bobiversum-reeks en verbindt ruimtevaart met vragen over identiteit, kopieën en verantwoordelijkheid.","sourceUrl":"https://metadata.isbn.nl/1470305/wij-zijn-legio-wij-zijn-bob.html","sourceType":"official_catalog","sourceName":"metadata.isbn.nl","supportingUrl":"https://metadata.isbn.nl/1470305/wij-zijn-legio-wij-zijn-bob.html","cover":"https://metadata.isbn.nl/ie_fcache/0000554867_Wij_zijn_legio__wij_zijn_Bob_0_0.jpg","coverSource":"https://metadata.isbn.nl/1470305/wij-zijn-legio-wij-zijn-bob.html","coverSha256":"7aa56ca16ce4557f991c431fc9f34ab41331d3f987d2480dd18e33b9041172b5","existingEdition":null},{"id":9313,"authorId":54,"author":"Jojo Moyes","ol":"OL15942682W","title":"De laatste liefdesbrief","isbn":"9789026138027","publisher":"De Fontein","format":"paperback","description":"Journalist Ellie vindt in een krantenarchief een oude liefdesbrief en wil weten welk verhaal erachter schuilt. In de jaren zestig probeert Jennifer na een ongeluk haar eigen verleden te reconstrueren. Ook voor haar vormt een brief een aanknopingspunt. De laatste liefdesbrief laat hun zoektochten elkaar raken. De roman onderzoekt hoe herinneringen, gemiste kansen en verwachtingen van anderen bepalen welke ruimte mensen aan een liefde geven.","sourceUrl":"https://openlibrary.org/works/OL15942682W","sourceType":"official_catalog","sourceName":"openlibrary.org","supportingUrl":"https://www.managementboek.nl/boek/9789026138027","cover":"https://static.boekenbalie.nl/media/24/14/0b/1625034217/boekenbalie_9789026138027_cover.jpg","coverSource":"https://boekenbalie.nl/de-laatste-liefdesbrief/9789026138027","coverSha256":"11dfb12dbf85bb37c44fe7dee67488f0a046f8cd3568755c97f9b05c380e4eb9","existingEdition":null},{"id":9318,"authorId":1543,"author":"Josh Malerman","ol":"OL19976661W","title":"De kooi","isbn":"9789400504615","publisher":"A.W. Bruna","format":"paperback","description":"Een onbekende dreiging maakt de buitenwereld dodelijk voor wie zijn ogen opent. Malorie voedt haar kinderen op achter afgesloten ramen en bereidt zich voor op een gevaarlijke tocht. Om een andere plek te bereiken moeten zij blindelings vertrouwen op geluid en op elkaar. De kooi, de Nederlandse vertaling van Bird Box, verbindt een overlevingsverhaal met de angst voor iets dat niet rechtstreeks kan worden waargenomen.","sourceUrl":"https://openlibrary.org/works/OL19976661W","sourceType":"official_catalog","sourceName":"openlibrary.org","supportingUrl":"https://www.deboekenplank.nl/nieuws/verschenen/nv_2015_01.htm","cover":"https://static.boekenbalie.nl/media/c0/d4/1b/1620293325/boekenbalie_9789400504615_cover.jpg","coverSource":"https://boekenbalie.nl/de-kooi/9789400504615","coverSha256":"0384d1e1c31048e5e030dfed9a19020f42385141224c19478e6b2d057a5cdc99","existingEdition":null},{"id":9402,"authorId":5415,"author":"Diane Setterfield","ol":"OL8454235W","title":"Het dertiende verhaal","isbn":"9789045848242","publisher":"Mouria","format":"paperback","description":"Een beroemde schrijfster vraagt een jonge biograaf haar levensverhaal vast te leggen. Wat volgt is een geschiedenis van familiebanden, een oud huis en geheimen die lang buiten beeld zijn gebleven. Het dertiende verhaal speelt met de verhouding tussen vertellen en verzwijgen. De roman past bij lezers die graag langzaam een verleden ontrafelen, met een uitgesproken gotische sfeer en veel aandacht voor de invloed van verhalen op een leven.","sourceUrl":"https://openlibrary.org/works/OL8454235W","sourceType":"official_catalog","sourceName":"openlibrary.org","supportingUrl":"https://www.bol.com/nl/nl/p/het-dertiende-verhaal/1001004004448456/","cover":"https://static.boekenbalie.nl/media/cc/84/a7/1657050595/boekenbalie_9789045848242_cover.jpg","coverSource":"https://boekenbalie.nl/het-dertiende-verhaal/9789045848242","coverSha256":"6af3bee2bc0984d3c47e3372601fcd0ad9651b3fc5bd0b7085ae44e9755d4ba1","existingEdition":null},{"id":9527,"authorId":5452,"author":"Michelle Paver","ol":"OL20625154W","title":"De geest van Gruhuken","isbn":"9789044328684","publisher":"The House of Books","format":"paperback","description":"Een jonge man sluit zich aan bij een expeditie naar het poolgebied. De afgelegen omgeving biedt eerst de kans op een nieuw begin, maar naarmate de winter en duisternis toenemen wordt het isolement beklemmender. Er lijkt iets aanwezig te zijn dat niet met gewone gevaren te verklaren is. De geest van Gruhuken is de Nederlandse vertaling van Michelle Pavers Dark Matter: een spookverhaal waarin landschap en angst nauw verbonden zijn.","sourceUrl":"https://openlibrary.org/works/OL20625154W","sourceType":"official_catalog","sourceName":"openlibrary.org","supportingUrl":"https://www.deslegte.com/de-geest-van-gruhuken-129924/","cover":"https://static.boekenbalie.nl/media/fb/2f/45/1625829618/boekenbalie_9789044328684_cover.jpg","coverSource":"https://boekenbalie.nl/de-geest-van-gruhuken/9789044328684","coverSha256":"ea6ca3c7d6c4cd8683412f789cc03dc4031813350ed8aa3a13b9049d08974694","existingEdition":null},{"id":9548,"authorId":5295,"author":"Debbie Macomber","ol":"OL1911650W","title":"De hoogste tijd!","isbn":"9789402756159","publisher":"Harlequin","format":"ebook","description":"Hallie besluit haar zoektocht naar een partner systematisch aan te pakken. Ze geeft zichzelf een jaar om een geschikte man te vinden, maar haar afspraken verlopen telkens anders dan gehoopt. Haar buurman Steve is een vertrouwde gesprekspartner, al lijken zij elkaar niet als mogelijke geliefden te zien. De hoogste tijd! combineert datingperikelen met een langzaam veranderende vriendschap. De hier getoonde Nederlandse editie is een afzonderlijk e-book.","sourceUrl":"https://www.harlequin.nl/collections/romantiek/products/debbie-macomber-de-hoogste-tijd","sourceType":"official_publisher","sourceName":"harlequin.nl","supportingUrl":"https://www.harlequin.nl/collections/romantiek/products/debbie-macomber-de-hoogste-tijd","cover":"https://www.harlequin.nl/cdn/shop/products/de_hoogste_tijd_9a31f4e0-1f00-4a4f-997e-a2d2e1d7388a.jpg","coverSource":"https://www.harlequin.nl/collections/romantiek/products/debbie-macomber-de-hoogste-tijd","coverSha256":"40fbc0a106e80869c8e613d14514c1d8f82565e4c02d5ae6dec40f5f52324080","existingEdition":null},{"id":9761,"authorId":590,"author":"Lisa See","ol":"OL31130116W","title":"De vrouwenkring van mevrouw Tan","isbn":"9789044368628","publisher":"The House of Books","format":"paperback","description":"Yunxian leert van jongs af aan over de gezondheid van vrouwen en raakt bevriend met een meisje dat als vroedvrouw wordt opgeleid. De verwachtingen van haar familie en haar latere huwelijk beperken de ruimte om die kennis te gebruiken. De vrouwenkring van mevrouw Tan verbeeldt het leven van Tan Yunxian in het China van de Ming-dynastie. Vriendschap, sociale regels en het doorgeven van kennis vormen de kern van de roman.","sourceUrl":"https://www.bibliotheek.nl/catalogus/titel.442717474.html/de-vrouwenkring-van-mevrouw-tan/","sourceType":"official_catalog","sourceName":"bibliotheek.nl","supportingUrl":"https://www.bibliotheek.nl/catalogus/titel.442717474.html/de-vrouwenkring-van-mevrouw-tan/","cover":"https://static.boekenbalie.nl/media/58/bf/9f/1740602222/boekenbalie_9789044368628_cover.jpg","coverSource":"https://boekenbalie.nl/de-vrouwenkring-van-mevrouw-tan/9789044368628","coverSha256":"a9f710ff27fea49e1c51a5cd4595c687a8eb0a9f8ebe04e749637ed7026bc6f1","existingEdition":null},{"id":9821,"authorId":5548,"author":"Miranda Cowley Heller","ol":"OL24630972W","title":"Het papieren paleis","isbn":"9789403112213","publisher":"De Bezige Bij","format":"paperback","description":"Elle verblijft met haar familie in het zomerhuis dat zij al sinds haar jeugd kent. Na een ontmoeting met haar oude vriend Jonas moet ze nadenken over haar huwelijk en de keuzes die haar leven hebben gevormd. Herinneringen aan eerdere zomers en pijnlijke gebeurtenissen dringen zich op. Het papieren paleis verbindt één beslissende dag met een veel langere familiegeschiedenis, waarin verlangen en oud verdriet moeilijk van elkaar te scheiden zijn.","sourceUrl":"https://www.bibliotheek.nl/catalogus/titel.433262982.html/het-papieren-paleis/","sourceType":"official_catalog","sourceName":"bibliotheek.nl","supportingUrl":"https://www.bibliotheek.nl/catalogus/titel.433262982.html/het-papieren-paleis/","cover":"https://static.boekenbalie.nl/media/cb/50/ea/1646858246/boekenbalie_9789403112213_cover.jpg","coverSource":"https://boekenbalie.nl/het-papieren-paleis/9789403112213","coverSha256":"e6a41687dcfabda624d5e1d40d48417052936b952bcea4b9bf93c9660849e10b","existingEdition":null},{"id":9908,"authorId":590,"author":"Lisa See","ol":"OL14927217W","title":"Snow Flower en de geheime waaier","isbn":"9789063053062","publisher":"Archipel","format":"paperback","description":"In het negentiende-eeuwse China ontstaat een hechte band tussen twee meisjes die opgroeien binnen strenge verwachtingen over het leven van vrouwen. Hun onderlinge communicatie biedt een ruimte die in de buitenwereld nauwelijks bestaat. Snow Flower en de geheime waaier volgt hoe die vriendschap door huwelijken, sociale verschillen en persoonlijke keuzes verandert. De roman kijkt naar verbondenheid en naar de schade die ook binnen een intieme relatie kan ontstaan.","sourceUrl":"https://www.bibliotheek.nl/catalogus/titel.285487884.html/snow-flower-en-de-geheime-waaier/","sourceType":"official_catalog","sourceName":"bibliotheek.nl","supportingUrl":"https://www.bibliotheek.nl/catalogus/titel.285487884.html/snow-flower-en-de-geheime-waaier/","cover":"https://static.boekenbalie.nl/media/11/84/60/1620370272/boekenbalie_9789063053062_cover.jpg","coverSource":"https://boekenbalie.nl/snow-flower-en-de-geheime-waaier/9789063053062","coverSha256":"abcd673c5f2803deacb08aa54bd3fae1141bd60663469343b98220f689dbd9fb","existingEdition":null},{"id":162,"authorId":129,"ol":"OL498556W","title":"De gedaanteverwisseling","isbn":"9789025327422","publisher":"Athenaeum- Polak & Van Gennep","language":"dut","format":"hardcover","description":null,"sourceUrl":"https://openlibrary.org/works/OL498556W","sourceName":"openlibrary.org","sourceType":"official_catalog","supportingUrl":"https://boekenbalie.nl/de-gedaanteverwisseling/9789025327422","cover":"https://static.boekenbalie.nl/media/c3/7c/8d/1620288598/b