nrandomhouse.com/books/93082/the-undomestic-goddess-by-sophie-kinsella/","sourceName":"penguinrandomhouse.com","sourceType":"official_publisher","supportingUrl":"https://boekenbalie.nl/aanpakken/9789085641384","cover":"https://static.boekenbalie.nl/media/ef/12/34/1671751519/boekenbalie_9789085641384_cover.jpg","coverSource":"https://boekenbalie.nl/aanpakken/9789085641384","coverSha256":"a7da903c50101aa1ffc9588c51eeeeea69367b2200d3a8a27faa5ca2a5e8f75c","existingEdition":1781,"beforeMetadata":null},{"id":1994,"authorId":104,"ol":"OL52114W","title":"The war of the worlds","isbn":"9789044606355","publisher":"Prometheus","language":"dut","format":"paperback","description":"In het Engelse landschap landen bezoekers van Mars, met technologie waar mensen nauwelijks iets tegen kunnen beginnen. Een verteller probeert zijn weg te vinden terwijl de vertrouwde samenleving in paniek raakt. The War of the Worlds laat een buitenaardse invasie zien vanuit kwetsbare menselijke ervaringen. Deze uitgave is de Nederlandse vertaling door Arie Storm. De roman verscheen oorspronkelijk in 1898 en is ook bekend onder de titel De oorlog der werelden.","sourceUrl":"https://openlibrary.org/works/OL52114W","sourceName":"openlibrary.org","sourceType":"official_catalog","supportingUrl":"https://boekenbalie.nl/the-war-of-the-worlds/9789044606355","cover":"https://static.boekenbalie.nl/media/7b/e8/ac/1620302024/boekenbalie_9789044606355_cover.jpg","coverSource":"https://boekenbalie.nl/the-war-of-the-worlds/9789044606355","coverSha256":"3ee3886525f797aa0afc87bbf4bce6f344cc47ddbf1b45a812f36fc880ff921f","existingEdition":2188,"beforeMetadata":null}]$records$::jsonb) LOOP
 SELECT m.edition_id INTO eid FROM public.catalog_edition_metadata m JOIN public.editions e ON e.id=m.edition_id JOIN public.works w ON w.id=e.work_id WHERE m.work_id=(r->>'id')::bigint AND m.review_batch='nl-reading-lists-complete-20261116' AND e.isbn_13=r->>'isbn' AND e.title=r->>'title' AND w.open_library_id=r->>'ol' AND w.author_id=(r->>'authorId')::bigint AND m.cover_url=r->>'cover' FOR UPDATE OF m,e,w;
 IF eid IS NULL THEN RAISE EXCEPTION 'Batch binding changed: %',r->>'id'; END IF;
 IF r->>'description' IS NOT NULL THEN
 DELETE FROM public.catalog_work_descriptions WHERE work_id=(r->>'id')::bigint AND language='nl' AND review_batch='nl-reading-lists-complete-20261116' AND text=r->>'description';
 IF NOT FOUND THEN RAISE EXCEPTION 'Description changed: %',r->>'id'; END IF;
 END IF;
 IF r->>'beforeMetadata' IS NOT NULL THEN
 SELECT * INTO before_row FROM jsonb_populate_record(NULL::public.catalog_edition_metadata,r->'beforeMetadata');
 UPDATE public.catalog_edition_metadata SET cover_url=before_row.cover_url,card_cover_url=before_row.card_cover_url,evidence=before_row.evidence,reviewed_at=before_row.reviewed_at,review_batch=before_row.review_batch WHERE edition_id=eid;
 ELSE
 DELETE FROM public.catalog_edition_metadata WHERE edition_id=eid;
 END IF;
 IF r->>'existingEdition' IS NULL THEN DELETE FROM public.editions WHERE id=eid; END IF;
END LOOP;
UPDATE public.works SET first_publish_year=2007 WHERE id=1646 AND author_id=875 AND open_library_id='OL26187306W' AND first_publish_year=2005;
